import json, re, subprocess, glob
REF="kvclcdjmjghndxsngfzb"; T=open('/tmp/sbp_token').read().strip()
def q(sql, timeout=50):
    p=subprocess.run(['curl','-s','-w','\n%{http_code}','--max-time',str(timeout),'-X','POST',
        '-H',f'Authorization: Bearer {T}','-H','Content-Type: application/json',
        '-d',json.dumps({'query':sql}),f'https://api.supabase.com/v1/projects/{REF}/database/query'],capture_output=True,text=True)
    body,_,code=p.stdout.rpartition('\n')
    return int(code or 0), body
# 1. collect column type defs from all repo SQL
defs={}
for f in glob.glob('expo/supabase/*.sql')+['expo/scripts/supabase-full-schema.sql']:
    s=open(f).read()
    for m in re.finditer(r'CREATE TABLE IF NOT EXISTS\s+(?:public\.)?"?(\w+)"?\s*\((.*?)\n\);', s, re.S|re.I):
        t=m.group(1).lower(); defs.setdefault(t,{})
        for line in m.group(2).split('\n'):
            c=line.strip().rstrip(',')
            if not c or c.upper().startswith(('PRIMARY','UNIQUE','CONSTRAINT','FOREIGN','CHECK','--')): continue
            parts=c.split()
            if len(parts)>=2:
                typ=re.sub(r'\b(NOT NULL|PRIMARY KEY|UNIQUE|REFERENCES.*|CHECK.*|DEFAULT.*)','',' '.join(parts[1:]),flags=re.I).strip()
                if typ: defs[t].setdefault(parts[0].strip('"').lower(), typ)
# 2. parse index statements from optimization file
opt=open('expo/supabase/IVX-ENTERPRISE-DB-OPTIMIZATION.sql').read()
need={}
for m in re.finditer(r'CREATE INDEX IF NOT EXISTS \w+ ON (?:public\.)?(\w+)\s*\(([^)]*)\)(?:\s*WHERE\s+([^;]+))?', opt, re.I):
    t=m.group(1).lower(); cols=[re.sub(r'\s+(DESC|ASC)$','',c.strip(),flags=re.I) for c in m.group(2).split(',')]
    if m.group(3): cols+=re.findall(r'(\w+)\s*(?:=|!=|IS)', m.group(3))
    need.setdefault(t,set()).update(c.lower() for c in cols if re.match(r'^\w+$',c))
# 3. get live columns
code,body=q("select table_name, column_name from information_schema.columns where table_schema='public'")
live={}
for r in json.loads(body): live.setdefault(r['table_name'],set()).add(r['column_name'])
alters=[]; missing_tables=[]
for t,cols in need.items():
    if t not in live: missing_tables.append(t); continue
    for c in cols-live[t]:
        typ=defs.get(t,{}).get(c,'text')
        alters.append(f'ALTER TABLE public.{t} ADD COLUMN IF NOT EXISTS {c} {typ};')
print('missing tables:',missing_tables)
print('alters needed:',len(alters))
for a in alters: print(' ',a)
if alters:
    code,body=q('\n'.join(alters))
    print('apply alters → HTTP',code, body[:200] if code!=201 else 'OK')
# create missing tables from defs if we have them
for t in missing_tables:
    if t in defs:
        colsql=', '.join(f'{c} {ty}' for c,ty in defs[t].items())
        code,body=q(f'CREATE TABLE IF NOT EXISTS public.{t} (id uuid primary key default gen_random_uuid(), {colsql});')
        print(f'created {t} → HTTP',code, body[:150] if code!=201 else '')
    else:
        print(f'no def found for {t} — creating minimal shell with needed cols')
        colsql=', '.join(f'{c} text' for c in need[t] if c!='id')
        code,body=q(f'CREATE TABLE IF NOT EXISTS public.{t} (id uuid primary key default gen_random_uuid(), {colsql});')
        print(f'created shell {t} → HTTP',code, body[:150] if code!=201 else '')
EOF
